body.script:
//
/*!
* jquery.counterup.js 1.0
* Copyright 2013, Benjamin Intal http://gambit.ph @bfintal
*/
(function($){"use strict";$.fn.counterUp=function(options){var settings=$.extend({'time':400,'delay':10},options);return this.each(function(){var $this=$(this);var $settings=settings;var counterUpper=function(){var nums=[];var divisions=$settings.time / $settings.delay;var num=$this.text();var isComma=/[0-9]+,[0-9]+/.test(num);num=num.replace(/,/g,'');var isInt=/^[0-9]+$/.test(num);var isFloat=/^[0-9]+\.[0-9]+$/.test(num);var decimalPlaces=isFloat?(num.split('.')[1]||[]).length:0;for(var i=divisions;i>=1;i--){var newNum=parseInt(num / divisions*i);if(isFloat){newNum=parseFloat(num / divisions*i).toFixed(decimalPlaces);}
if(isComma){while(/(\d+)(\d{3})/.test(newNum.toString())){newNum=newNum.toString().replace(/(\d+)(\d{3})/,'$1'+','+'$2');}}
nums.unshift(newNum);}
$this.data('counterup-nums',nums);$this.text('0');var f=function(){$this.text($this.data('counterup-nums').shift());if($this.data('counterup-nums').length){setTimeout($this.data('counterup-func'),$settings.delay);}else{delete $this.data('counterup-nums');$this.data('counterup-nums',null);$this.data('counterup-func',null);}};$this.data('counterup-func',f);setTimeout($this.data('counterup-func'),$settings.delay);};$this.waypoint(function(direction){counterUpper();this.destroy();},{offset:'100%'});});};})(jQuery);

jQuery(document).ready(function($) {
    $('.counter-info .counter-title').counterUp({
        delay: 10,
        time: 3000
    });

    $('.counter-box-info,.counter-box-image').matchHeight();
});

$(document)["ready"](function() {
    "use strict";
    var a = $(window);
    $(".full-height, #main-intro .container")["height"](a["height"]());
    a["on"]("resize", function() {
        $(".full-height")["height"](a["height"]());
    });
    $('#parallax-menu ul,.slide-in').onePageNav({
        currentClass: 'current',
        changeHash: false,
        scrollSpeed: 750
    });
    $('#parallax-menu ul').clone().appendTo('.scrolling-mobile-menu');
    $('.scrolling-mobile-menu-toggle').on('click', function() {
        $('body').toggleClass('scrolling-active');
        $('.overlay').fadeToggle(170);
    });
    $("#testimonial").owlCarousel({
        items: 2,
        slideBy: 1,
        smartSpeed: 1000,
        animateIn: 'fadeInRight',
        animateOut: 'fadeOutRight',
        rtl: false,
        nav: false,
        navText: ['', ''],
        loop: true,
        autoplay: false,
        autoplayHoverPause: true,
        dots: true,
        mouseDrag: false,
        touchDrag: false,
        freeDrag: false,
        pullDrag: false,
        responsive: {
            0: {items: 1},
            541: {items: 1},
            767: {items: 2}
        }
    });
});

